type EditFilesOptions struct {
	GetWorkspaceConn func(context.Context) (workspacesdk.AgentConn, error)
	ResolvePlanPath  func(context.Context) (chatPath string, home string, err error)
	IsPlanTurn       bool
}

// EditFilesArgs is the tool input schema, auto-generated by the
// fantasy framework from these struct tags.
type EditFilesArgs struct {
	Edits []EditFilesEdit `json:"edits"`
}

// EditFilesEdit is a single edit that, unlike workspacesdk.FileEdit,
// carries the path of the file it changes.
type EditFilesEdit struct {
	Path       string `json:"path" description:"Absolute path of the file, for example /home/coder/project/main.go."`
	OldText    string `json:"old_text" description:"Text to replace. Must match one location unless replace_all is set. Whitespace and indentation differences are tolerated."`
	NewText    string `json:"new_text" description:"Replacement text. Must differ from old_text."`
	ReplaceAll bool   `json:"replace_all,omitempty" description:"Replace every match of old_text."`
}

// GroupEditsByPath groups edits into one file per path for the
// workspace agent request. Paths are compared exactly as given. Files
// are ordered by each path's first edit, and each file keeps its edits
// in their original order. Empty input returns an empty slice, not nil.
func GroupEditsByPath(edits []EditFilesEdit) []workspacesdk.FileEdits {
	files := make([]workspacesdk.FileEdits, 0, len(edits))
	indexByPath := make(map[string]int, len(edits))
	for _, edit := range edits {
		i, ok := indexByPath[edit.Path]
		if !ok {
			i = len(files)
			indexByPath[edit.Path] = i
			files = append(files, workspacesdk.FileEdits{Path: edit.Path})
		}
		files[i].Edits = append(files[i].Edits, workspacesdk.FileEdit{
			OldText:    edit.OldText,
			NewText:    edit.NewText,
			ReplaceAll: edit.ReplaceAll,
		})
	}
	return files
}

// EditFilesHookInput is edit_files input grouped by path, in the shape
// pre_tool_use hooks read as tool_input and send as input_override.
//
// It does not reuse workspacesdk.FileEdits: hooks must see and send
// only old_text/new_text, but the JSON methods on workspacesdk.FileEdit
// also write the deprecated search/replace keys and fall back to
// reading them.
type EditFilesHookInput struct {
	Files []EditFilesHookFile `json:"files"`
}

// EditFilesHookFile holds the edits for one path in
// EditFilesHookInput.
type EditFilesHookFile struct {
	Path  string              `json:"path"`
	Edits []EditFilesHookEdit `json:"edits"`
}

// EditFilesHookEdit is one edit in EditFilesHookFile.
type EditFilesHookEdit struct {
	OldText    string `json:"old_text"`
	NewText    string `json:"new_text"`
	ReplaceAll bool   `json:"replace_all,omitempty"`
}

// NewEditFilesHookInput groups edits by path with the same ordering
// as GroupEditsByPath.
func NewEditFilesHookInput(edits []EditFilesEdit) EditFilesHookInput {
	grouped := GroupEditsByPath(edits)
	input := EditFilesHookInput{Files: make([]EditFilesHookFile, 0, len(grouped))}
	for _, file := range grouped {
		hookFile := EditFilesHookFile{
			Path:  file.Path,
			Edits: make([]EditFilesHookEdit, 0, len(file.Edits)),
		}
		for _, edit := range file.Edits {
			hookFile.Edits = append(hookFile.Edits, EditFilesHookEdit(edit))
		}
		input.Files = append(input.Files, hookFile)
	}
	return input
}

// Edits flattens the grouped input: files in order, then each file's
// edits in order. It returns an empty slice, not nil, when there are no
// edits.
func (in EditFilesHookInput) Edits() []EditFilesEdit {
	edits := make([]EditFilesEdit, 0)
	for _, file := range in.Files {
		for _, edit := range file.Edits {
			edits = append(edits, EditFilesEdit{
				Path:       file.Path,
				OldText:    edit.OldText,
				NewText:    edit.NewText,
				ReplaceAll: edit.ReplaceAll,
			})
		}
	}
	return edits
}

// EditFilesName is the name of the edit_files tool.
const EditFilesName = "edit_files"

// NormalizeEditPaths returns a copy of edits with each path in the form
// the tool uses it: surrounding whitespace removed.
func NormalizeEditPaths(edits []EditFilesEdit) []EditFilesEdit {
	normalized := slices.Clone(edits)
	for i := range normalized {
		normalized[i].Path = strings.TrimSpace(normalized[i].Path)
	}
	return normalized
}

// editFilesExample is the input example shown when the model sends a
// shape the tool does not accept.
const editFilesExample = `{"edits":[{"path":"/repo/a.go","old_text":"x := 1","new_text":"x := 2"},{"path":"/repo/b.go","old_text":"foo()","new_text":"bar()"}]}`

// editFilesTool adds input handling that the typed fantasy wrapper
// cannot express: a decoder chatloop applies to a string-encoded edits
// array, and whole-call errors that show the accepted shape.
type editFilesTool struct {
	fantasy.AgentTool
}

// DecodeToolInput replaces a top-level edits value that is a JSON
// string with the string's content when that content parses as-is into
// a JSON array of objects. Nothing is re-encoded, so the ambiguity
// check still sees the model's key spelling. Any other input returns
// false; a repeated or differently capitalized edits key is left for the
// ambiguity check to reject.
func (editFilesTool) DecodeToolInput(input string) (string, bool) {
	decoder := json.NewDecoder(strings.NewReader(input))
	if token, err := decoder.Token(); err != nil || token != json.Delim('{') {
		return "", false
	}
	var (
		content    string
		start, end = -1, -1
	)
	for decoder.More() {
		token, err := decoder.Token()
		if err != nil {
			return "", false
		}
		key, _ := token.(string)
		var value json.RawMessage
		if err := decoder.Decode(&value); err != nil {
			return "", false
		}
		if key != "edits" {
			continue
		}
		if start >= 0 {
			return "", false
		}
		if err := json.Unmarshal(value, &content); err != nil {
			return "", false
		}
		end = int(decoder.InputOffset())
		start = end - len(value)
	}
	if token, err := decoder.Token(); err != nil || token != json.Delim('}') {
		return "", false
	}
	if _, err := decoder.Token(); !errors.Is(err, io.EOF) {
		return "", false
	}
	if start < 0 || !isJSONArrayOfObjects(content) {
		return "", false
	}
	return input[:start] + content + input[end:], true
}

// isJSONArrayOfObjects reports whether text is exactly one JSON array
// whose elements are all objects. json.Unmarshal accepts only JSON
// whitespace around the value, so text that passes can be spliced into
// the input unchanged.
func isJSONArrayOfObjects(text string) bool {
	var items []json.RawMessage
	if err := json.Unmarshal([]byte(text), &items); err != nil || items == nil {
		return false
	}
	for _, item := range items {
		if !strings.HasPrefix(strings.TrimLeft(string(item), " \t\r\n"), "{") {
			return false
		}
	}
	return true
}

// Run rejects the retired files shape and input that does not decode
// into EditFilesArgs. Both messages start with what to change and show
// the accepted shape; the decode message also carries the decode error.
func (t editFilesTool) Run(ctx context.Context, call fantasy.ToolCall) (fantasy.ToolResponse, error) {
	var retired struct {
		Files json.RawMessage `json:"files"`
	}
	if err := json.Unmarshal([]byte(call.Input), &retired); err == nil && retired.Files != nil {
		return rejectEditFiles(
			"Send edits as a list where each edit has path, old_text and new_text, for example: " + editFilesExample +
				"; the files key is not supported",
		), nil
	}
	var args EditFilesArgs
	if err := json.Unmarshal([]byte(call.Input), &args); err != nil {
		return rejectEditFiles(fmt.Sprintf(
			"Send edits as a JSON array of objects with string path, old_text and new_text, and optional boolean replace_all, for example %s; decoding failed (%s)",
			editFilesExample, err,
		)), nil
	}
	return t.AgentTool.Run(ctx, call)
}

func EditFiles(options EditFilesOptions) fantasy.AgentTool {
	return editFilesTool{AgentTool: fantasy.NewAgentTool(
		EditFilesName,
		"Edit files by replacing old_text with new_text. Edits to the same"+
			" file apply in order. If any edit to a file fails, that file is"+
			" left unchanged; other files are still edited.",
		func(ctx context.Context, args EditFilesArgs, _ fantasy.ToolCall) (fantasy.ToolResponse, error) {
			if len(args.Edits) == 0 {
				return rejectEditFiles("Add at least one edit to edits"), nil
			}
			var missingPath []string
			args.Edits = NormalizeEditPaths(args.Edits)
			for i, edit := range args.Edits {
				if edit.Path == "" {
					missingPath = append(missingPath, fmt.Sprintf("edits[%d]", i))
				}
			}
			if len(missingPath) > 0 {
				return rejectEditFiles(
					"Set path to the absolute path of the file to edit in " + strings.Join(missingPath, ", "),
				), nil
			}
			var planPath string
			if options.IsPlanTurn {
				resolvedPlanPath, err := resolvePlanTurnPath(ctx, options.ResolvePlanPath)
				if err != nil {
					return rejectEditFiles(err.Error()), nil
				}
				for _, edit := range args.Edits {
					if edit.Path != resolvedPlanPath {
						return rejectEditFiles("Edit only " + resolvedPlanPath + "; during plan turns, edit_files is restricted to that file"), nil
					}
				}
				planPath = resolvedPlanPath
			}
			if options.GetWorkspaceConn == nil {
				return rejectEditFiles("workspace connection resolver is not configured"), nil
			}
			conn, err := options.GetWorkspaceConn(ctx)
			if err != nil {
				return rejectEditFiles(err.Error()), nil
			}
			if planPath != "" {
				if err := ensurePlanPathResolvesToItself(ctx, conn, planPath); err != nil {
					return rejectEditFiles(err.Error()), nil
				}
			}
			return executeEditFilesTool(ctx, conn, args, options.ResolvePlanPath)
		},
	)}
}

// executeEditFilesTool applies each file in its own agent request, in
// order of each path's first edit, so a file with an error does not
// stop the others. Results index edits by their position in args.
func executeEditFilesTool(
	ctx context.Context,
	conn workspacesdk.AgentConn,
	args EditFilesArgs,
	resolvePlanPath func(context.Context) (chatPath string, home string, err error),
) (fantasy.ToolResponse, error) {
	editIndexes := make(map[string][]int)
	for i, edit := range args.Edits {
		editIndexes[edit.Path] = append(editIndexes[edit.Path], i)
	}

	var (
		chatPath       string
		home           string
		planPathErr    error
		planPathLoaded bool
	)
	// checkPath runs the coderd checks tied to one path and returns the
	// reason to reject that file, or "" when it passes.
	checkPath := func(path string) string {
		hasPlanFileName := looksLikePlanFileName(path)
		if hasPlanFileName && !isAbsolutePath(path) {
			return "Use the chat-specific absolute plan path; plan files must use absolute paths"
		}
		if resolvePlanPath == nil || !hasPlanFileName {
			return ""
		}
		if !planPathLoaded {
			chatPath, home, planPathErr = resolvePlanPath(ctx)
			planPathLoaded = true
		}
		if resp, rejected := rejectSharedPlanPath(path, home, chatPath, planPathErr); rejected {
			return resp.Content
		}
		return ""
	}

	// notApplied holds the files entries that were not applied. reports
	// holds, in file order, every group of edits the message lists as
	// not applied: those entries and the no-ops dropped from files that
	// were sent.
	var applied, notApplied, reports []editFilesFileResult
	appliedEdits := 0
	for _, file := range GroupEditsByPath(args.Edits) {
		indexes := editIndexes[file.Path]
		reject := func(result editFilesFileResult) {
			notApplied = append(notApplied, result)
			reports = append(reports, result)
		}
		// The interrupt handler can persist this result, so a file not yet
		// sent is reported as not applied; sending it now would fail and
		// report its outcome as unknown. This check runs before checkPath
		// so the interrupt is the reason given.
		if ctx.Err() != nil {
			reject(editFilesFileResult{
				Path: file.Path, Status: editFilesStatusRejected, Edits: indexes, Error: editFilesInterruptedError,
			})
			continue
		}
		if reason := checkPath(file.Path); reason != "" {
			reject(editFilesFileResult{
				Path: file.Path, Status: editFilesStatusRejected, Edits: indexes, Error: reason,
			})
			continue
		}
		// An edit whose old_text equals new_text changes nothing, so it is
		// dropped and reported instead of sent and reported as applied;
		// the rest of its file is still sent. The comparison is byte for
		// byte because texts that differ only in whitespace or line
		// endings can still change the file.
		sent := workspacesdk.FileEdits{Path: file.Path}
		var sentIndexes, noOps []int
		for j, edit := range file.Edits {
			if edit.OldText == edit.NewText {
				noOps = append(noOps, indexes[j])
				continue
			}
			sent.Edits = append(sent.Edits, edit)
			sentIndexes = append(sentIndexes, indexes[j])
		}
		if len(noOps) > 0 {
			noOpResult := editFilesFileResult{
				Path: file.Path, Status: editFilesStatusRejected, Edits: noOps, Error: editFilesNoOpError,
			}
			if len(sent.Edits) == 0 {
				reject(noOpResult)
				continue
			}
			reports = append(reports, noOpResult)
		}
		resp, err := conn.EditFiles(ctx, workspacesdk.FileEditRequest{
			Files:       []workspacesdk.FileEdits{sent},
			IncludeDiff: true,
		})
		if err != nil {
			// An agent response means nothing was written: the agent
			// validates the file, writes a temporary file and renames it
			// into place, and only a panic after the rename returns an
			// error after writing. A dropped connection may follow a
			// completed write.
			status := editFilesStatusUnknown
			if isAgentResponse(err) {
				status = editFilesStatusRejected
			}
			reject(editFilesFileResult{
				Path: file.Path, Status: status, Edits: sentIndexes, Error: agentAPIErrorMessage(err),
			})
			continue
		}
		result := editFilesFileResult{Path: file.Path, Status: editFilesStatusApplied}
		// Agents that predate per-file results return none.
		if len(resp.Files) > 0 {
			diff := resp.Files[0].Diff
			result.Diff = &diff
		}
		applied = append(applied, result)
		appliedEdits += len(sentIndexes)
	}

	message := editFilesResultMessage(appliedEdits, len(args.Edits), reports)
	switch {
	case appliedEdits == len(args.Edits):
		return marshalToolResponse(editFilesResult{
			Status:  editFilesStatusApplied,
			Message: message,
			Files:   applied,
		}), nil
	case appliedEdits > 0:
		return marshalToolResponse(editFilesResult{
			Status:  editFilesStatusPartial,
			Message: message,
			Files:   append(notApplied, applied...),
		}), nil
	default:
		return fantasy.NewTextErrorResponse(message), nil
	}
}

// isAgentResponse reports whether an EditFiles error carries the
// agent's response rather than a transport or decoding failure.
func isAgentResponse(err error) bool {
	_, ok := codersdk.AsError(err)
	return ok
}

// editFilesResultMessage counts the applied edits out of total, then
// lists one line per entry of reports, in order, with edits of unknown
// outcome under their own heading.
func editFilesResultMessage(applied, total int, reports []editFilesFileResult) string {
	var rejected, unknown []string
	for _, file := range reports {
		prefix := "\n- " + formatEditIndexes(file.Edits) + " (" + file.Path + "): "
		// Each line appends a sentence to the error, so its own trailing
		// periods and spaces are trimmed to avoid "..".
		reason := strings.TrimRight(file.Error, ". ")
		switch {
		case file.Status == editFilesStatusUnknown:
			unknown = append(unknown, prefix+reason+". Re-read "+file.Path+" before resending these edits.")
		case file.Error == editFilesInterruptedError:
			rejected = append(rejected, prefix+reason+".")
		case file.Error == editFilesNoOpError:
			rejected = append(rejected, prefix+reason+". If you meant to change this text, resend the edit with the new text.")
		default:
			rejected = append(rejected, prefix+reason+". "+file.Path+" is unchanged; fix and resend only these edits.")
		}
	}
	var sb strings.Builder
	_, _ = fmt.Fprintf(&sb, "Applied %d of %d edits.", applied, total)
	// The first heading follows the count on the same line; a later one
	// starts its own line.
	separator := " "
	for _, section := range []struct {
		heading string
		lines   []string
	}{
		{"Not applied:", rejected},
		{"Unknown whether applied:", unknown},
	} {
		if len(section.lines) == 0 {
			continue
		}
		_, _ = sb.WriteString(separator + section.heading + strings.Join(section.lines, ""))
		separator = "\n"
	}
	return sb.String()
}

// editFilesInterruptedError is the error of a file that was not sent
// because the tool call was interrupted. Nothing is known to be wrong
// with such a file, and the user may have interrupted to stop it, so
// its line has no resend instruction.
const editFilesInterruptedError = "not sent because the tool call was interrupted"

// editFilesNoOpError is the error of edits whose old_text equals
// new_text. They were not sent, so their line says to resend them only
// if a change was meant.
const editFilesNoOpError = "old_text equals new_text, so it would change nothing"

// formatEditIndexes renders indexes as "edits[1], edits[3]".
func formatEditIndexes(indexes []int) string {
	parts := make([]string, 0, len(indexes))
	for _, i := range indexes {
		parts = append(parts, fmt.Sprintf("edits[%d]", i))
	}
	return strings.Join(parts, ", ")
}

// editFilesNoneApplied ends every whole-call rejection.
const editFilesNoneApplied = "No edits were applied."

// File and result statuses in edit_files results.
const (
	editFilesStatusApplied  = "applied"
	editFilesStatusPartial  = "partial"
	editFilesStatusRejected = "rejected"
	editFilesStatusUnknown  = "unknown"
)

// editFilesResult is the edit_files tool result when at least one file
// was applied. Files that were not applied come first.
type editFilesResult struct {
	Status  string                `json:"status"`
	Message string                `json:"message"`
	Files   []editFilesFileResult `json:"files"`
}

// editFilesFileResult is the outcome for one file in editFilesResult.
type editFilesFileResult struct {
	Path   string `json:"path"`
	Status string `json:"status"`
	// Edits holds the edits[i] indexes of a file that was not applied.
	// The agent does not say which edit failed, so it lists them all.
	Edits []int  `json:"edits,omitempty"`
	Error string `json:"error,omitempty"`
	// Diff is the agent's diff for an applied file, nil when the agent
	// returned no per-file result.
	Diff *string `json:"diff,omitempty"`
}

// rejectEditFiles returns a whole-call rejection decided before any
// edit request reached the agent, so no file was written.
func rejectEditFiles(reason string) fantasy.ToolResponse {
	return fantasy.NewTextErrorResponse(reason + "\n" + editFilesNoneApplied)
}

// agentAPIErrorMessage preserves the agent's actionable message while
// dropping the transport metadata (HTTP method, URL, status code) that
// codersdk.Error.Error() prefixes.
func agentAPIErrorMessage(err error) string {
	sdkErr, ok := codersdk.AsError(err)
	if !ok || sdkErr.Message == "" {
		return err.Error()
	}
	var sb strings.Builder
	_, _ = sb.WriteString(sdkErr.Message)
	if sdkErr.Helper != "" {
		_, _ = sb.WriteString(": " + sdkErr.Helper)
	}
	if sdkErr.Detail != "" {
		_, _ = sb.WriteString(": " + sdkErr.Detail)
	}
	for _, v := range sdkErr.Validations {
		_, _ = sb.WriteString("\n- " + v.Field + ": " + v.Detail)
	}
	return sb.String()
}
